}


def hash_password(password):
    """对明文密码做 MD5 哈希。"""
    return hashlib.md5(password.encode("utf-8")).hexdigest()


def login(username, password):
    """校验用户名与密码。

    返回 (是否成功, 提示信息)。
    """
    if username not in USER_TABLE:
        return False, "用户不存在"

    if USER_TABLE[username] != password:<redacted>, "密码错误"

    return True, "登录成功"


